import {EXERCISES,exerciseById} from './exercises.js';
export const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
export const addDays=(iso,n)=>{const d=new Date(iso+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
export const dayOf=iso=>new Date(iso+'T12:00:00Z').getUTCDay();
export const difference=(a,b)=>Math.round((new Date(a+'T12:00:00Z')-new Date(b+'T12:00:00Z'))/86400000);
export function todayISO(timeZone='Africa/Nairobi'){return new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
export function defaultProfile(){return {name:'',goal:'muscle',secondary:'fitness',experience:0,days:[1,3,5],slots:{0:30,1:30,2:30,3:30,4:30,5:30,6:30},locations:{0:'home',1:'home',2:'home',3:'home',4:'home',5:'home',6:'home'},equipment:{home:['dumbbells','ball','wall'],gym:['dumbbells']},dumbbellKg:5,band:'My band',excluded:[],wheelReady:false,adult:true,individual:false,time:'07:00',timezone:'Africa/Nairobi',start:todayISO(),runningKm:0,longestKm:0,pace:7,raceDate:'',longDay:0};}
export function eligible(ex,p,location='home') {return ex.equipment.every(k=>(p.equipment[location]||[]).includes(k))&&ex.level<=Number(p.experience)&&!p.excluded.includes(ex.id)&&(!ex.advancedOptIn||p.wheelReady);}
export function loadFor(ex,p){if(ex.load==='single')return {kg:Number(p.dumbbellKg),label:`${p.dumbbellKg} kg held in both hands`};if(ex.load==='pair')return {kg:Number(p.dumbbellKg),label:`${p.dumbbellKg} kg per hand`};if(ex.load==='band')return {kg:0,label:p.band||'Your resistance band'};if(ex.load==='machine'||ex.load==='barbell')return {kg:0,label:'Choose a manageable load and record it'};return {kg:0,label:'Bodyweight'};}
export function estimateItem(i){const e=exerciseById(i.exerciseId);return i.sets*((e.timed?i.reps:i.reps*e.secondsPerRep)*(e.unilateral?2:1)+i.rest)+25;}
export function estimateSession(s){if(s.kind==='run')return s.runMinutes*60;return 4*60+s.items.reduce((n,i)=>n+estimateItem(i),0)+3*60+60;}
export function validateProfile(p){const errors=[];if(!p.adult)errors.push('These programmes are designed for adults.');if(p.individual)errors.push('An individual programme is more suitable for the restrictions you reported. You can still browse the exercise library.');if(!Object.keys({strength:1,muscle:1,fitness:1,running:1,marathon:1}).includes(p.goal))errors.push('Choose a supported goal.');if(!p.days.length)errors.push('Choose at least one workout day.');if(p.days.some(d=>!Number.isInteger(+p.slots[d])||p.slots[d]<15||p.slots[d]>300))errors.push('Choose between 15 and 300 minutes for each selected day.');if(!/^\d{4}-\d{2}-\d{2}$/.test(p.start)||Number.isNaN(Date.parse(p.start)))errors.push('Choose a valid starting date.');if(!Number.isFinite(+p.dumbbellKg)||p.dumbbellKg<=0||p.dumbbellKg>200)errors.push('Enter a dumbbell weight above zero and no more than 200 kg.');if(!Number.isFinite(+p.pace)||p.pace<3||p.pace>15)errors.push('Choose an easy running pace from 3 to 15 minutes per km.');return errors;}
function item(ex,p){const muscle=p.goal==='muscle';return {exerciseId:ex.id,sets:2,reps:ex.timed?20:ex.unilateral?6:muscle?10:8,min:ex.timed?15:ex.unilateral?5:8,max:ex.timed?35:ex.unilateral?10:12,rest:p.goal==='strength'?100:75,load:loadFor(ex,p)};}
function score(e,pattern,p,location,variant){let score=e.equipment.length?2:0;if(p.goal==='fitness'&&e.level===0)score+=1;if(location==='gym'&&['leg-press','cable-row','lat-pull','bench'].includes(e.id))score+=4;if(pattern==='hinge'&&e.id==='hinge')score+=3;if(pattern==='core'&&e.id===(variant%2?'birddog':'deadbug'))score+=4;if(pattern==='squat'&&e.id==='goblet')score+=4;if(pattern==='push'&&e.id==='floor-press')score+=3;if(pattern==='pull'&&e.id==='row')score+=3;return score;}
export function strengthSession(p,date,variant=0,minutesOverride=null){const location=p.locations[dayOf(date)]||'home';const cap=minutesOverride||p.slots[dayOf(date)];const patterns=['squat','hinge','push','pull','core'];const picks=[];const missing=[];for(const pattern of patterns){const options=EXERCISES.filter(e=>e.pattern===pattern&&eligible(e,p,location)).sort((a,b)=>score(b,pattern,p,location,variant)-score(a,pattern,p,location,variant));if(options[0])picks.push(item(options[0],p));else missing.push(pattern);}
 const s={id:uid(),date,location,kind:'strength',title:`Full body ${variant%2?'B':'A'}`,goal:p.goal,budget:cap,status:'planned',items:picks,createdAt:new Date().toISOString(),note:variant%2?'Repeat the foundations with a different core movement.':'Practise the same movements and record what you complete.',missing};
 // Keep the movement patterns and suitable rests. Reduce sets before omitting optional work.
 while(estimateSession(s)>cap*60&&s.items.some(i=>i.sets>1)){const next=[...s.items].reverse().find(i=>i.sets>1);next.sets--;}
 if((p.goal==='fitness'||p.secondary==='fitness')&&estimateSession(s)+150<=cap*60){const march=exerciseById('march');s.items.push({...item(march,p),sets:1,reps:90,min:45,max:120,rest:20});}
 if(p.secondary==='muscle'&&p.goal!=='muscle'){const extra=item(exerciseById('curl'),p);extra.sets=1;if(eligible(exerciseById('curl'),p,location)&&estimateSession(s)+estimateItem(extra)<=cap*60)s.items.push(extra);}s.seconds=estimateSession(s);s.fits=s.seconds<=cap*60;s.missing=missing;
 return s;}
export function createPlan(p){const errors=validateProfile(p);if(errors.length)return {errors,warnings:[],sessions:[]};if(['running','marathon'].includes(p.goal))return runningPlan(p);const sessions=[];const warnings=[];if(p.days.length===1)warnings.push('One day is a useful start. This schedule does not provide twice weekly strength work.');let index=0;for(let n=0;n<28;n++){const date=addDays(p.start,n);if(!p.days.includes(dayOf(date)))continue;const prev=sessions.at(-1);if(prev&&difference(date,prev.date)<2){warnings.push('Consecutive strength days were changed to recovery days. Choose separated days for more sessions.');continue;}const s=strengthSession(p,date,index++);if(s.missing.length)errors.push(`Your ${s.location} setup has no suitable ${s.missing.join(', ')} movement. Add equipment or remove an exclusion.`);if(!s.fits)errors.push(`The ${s.budget} minute slot on ${date} is too short for this full body template. Allow more time.`);sessions.push(s);}
 if(!sessions.length)errors.push('No sessions fit the selected days.');return {errors:[...new Set(errors)],warnings:[...new Set(warnings)],sessions:errors.length?[]:sessions,summary:'A four week starting block. Progression is suggested from your recorded results, never assumed.'};}
function runSession(p,date,minutes,title,segments,week,extra={}){return {id:uid(),date,location:'outdoors',kind:'run',title,goal:p.goal,budget:p.slots[dayOf(date)],status:'planned',items:[],runMinutes:minutes,segments,week,...extra};}
function runningPlan(p){const errors=[],warnings=[],sessions=[];const days=[...p.days].sort();if(days.length<3)errors.push('Running foundation needs at least three separated days.');if(p.days.some((d,i)=>p.days.some((o,j)=>i!==j&&((d-o+7)%7===1))))warnings.push('Choose separated running days when possible. Adjacent foundation runs will be skipped.');if(p.goal==='running'){
  let index=0;for(let n=0;n<56;n++){const date=addDays(p.start,n);if(!days.includes(dayOf(date)))continue;if(sessions.at(-1)&&difference(date,sessions.at(-1).date)<2)continue;const week=Math.floor(n/7)+1;const run=[1,1.5,2,2.5,3,4,5,6][week-1],walk=2;const rounds=Math.min(4,Math.max(1,Math.floor((p.slots[dayOf(date)]-10)/(run+walk))));const minutes=10+rounds*(run+walk);if(p.slots[dayOf(date)]<Math.ceil(minutes)){errors.push(`Week ${week} needs ${Math.ceil(minutes)} minutes on ${date}, including walking. Increase that time slot.`);continue;}const segments=[{label:'Warm up walk',seconds:300}];for(let j=0;j<rounds;j++)segments.push({label:'Easy run',seconds:run*60},{label:'Walk recovery',seconds:walk*60});segments.push({label:'Cool down walk',seconds:300});sessions.push(runSession(p,date,minutes,`Run and walk ${++index}`,segments,week,{note:'Use a conversational effort. Repeat a week if it feels too demanding.'}));}
  if(Array.from({length:8},(_,n)=>sessions.filter(s=>s.week===n+1).length).some(n=>n<3))errors.push('Choose days that allow at least three separated foundation runs each week.');return {errors:[...new Set(errors)].slice(0,4),warnings,sessions:errors.length?[]:sessions,summary:'An original eight week run and walk draft. It builds time gradually and can be repeated, rather than promising a finishing distance.'};
 }
 if(p.days.length<4)errors.push('Marathon preparation needs at least four available running days in this planner.');if(!p.raceDate||difference(p.raceDate,p.start)<112)errors.push('Choose a race at least 16 weeks after the starting date.');if(difference(p.raceDate,p.start)>182)errors.push('Choose a marathon block starting 16 to 26 weeks before the race. Build your running base before that block.');if(p.runningKm<20||p.longestKm<8)errors.push('This marathon draft starts from at least 20 km per week and a recent 8 km long run. Build your running base first.');if(p.longestKm>p.runningKm)errors.push('Your longest recent run cannot exceed your current total weekly distance.');if(!p.days.includes(Number(p.longDay)))errors.push('Choose an available day for the long run.');if(p.slots[p.longDay]<180)errors.push('Allow at least 180 minutes on the long run day. The plan will check the exact peak duration too.');if(errors.length)return {errors,warnings,sessions:[]};
 const weeks=Math.ceil(difference(p.raceDate,p.start)/7);let weekly=Number(p.runningKm),long=Number(p.longestKm);const runDays=days.filter(d=>d!==Number(p.longDay)).slice(0,3);let peak=0;
 for(let w=0;w<weeks;w++){const remain=weeks-1-w;const recovery=w>0&&w%4===3;const taper=remain<3;const target=taper?Math.max(p.runningKm*.55,weekly*[.55,.7,.85][remain]):recovery?weekly*.8:Math.min(60,weekly*(w?1.06:1));const longKm=taper?Math.max(5,long*[.3,.5,.7][remain]):recovery?long*.75:Math.min(30,long*(w?1.08:1));if(!recovery&&!taper){weekly=target;long=longKm;}peak=Math.max(peak,longKm);let longDate=null;for(let n=0;n<7;n++){const date=addDays(p.start,w*7+n);if(date<p.raceDate&&dayOf(date)===Number(p.longDay))longDate=date;}const otherKm=Math.max(0,target-longKm)/3;
  for(let n=0;n<7;n++){const date=addDays(p.start,w*7+n);if(date>=p.raceDate)continue;const d=dayOf(date);if(d!==Number(p.longDay)&&!runDays.includes(d))continue;const isLong=d===Number(p.longDay);const km=isLong?longKm:otherKm;const mins=Math.ceil(km*p.pace+10);if(mins>p.slots[d])errors.push(`Week ${w+1} needs ${mins} minutes on ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d]}. Increase that slot or revise the goal.`);sessions.push(runSession(p,date,mins,isLong?'Easy long run':'Easy run',[{label:'Warm up walk',seconds:300},{label:'Easy conversational run',seconds:Math.max(60,(mins-10)*60)},{label:'Cool down walk',seconds:300}],w+1,{km:Math.round(km*10)/10,note:taper?'Taper week. Reduce training before the race.':recovery?'Recovery week. Lower volume before building again.':'Easy effort. Do not chase a time target.'}));}
 }
 if(peak<24)errors.push('This starting base and race date do not build to the long run range used by this template. Start earlier or build your base first.');if(errors.length)return {errors:[...new Set(errors)].slice(0,5),warnings,sessions:[]};warnings.push('This is an adjustable training draft, not a guarantee of marathon readiness. Review it with a qualified running coach.');return {errors,warnings,sessions,summary:`A ${weeks} week easy running draft with recovery weeks and a three week taper. Race day is kept separate from training.`};}
export function scheduleConflicts(sessions,id,date){const source=sessions.find(s=>s.id===id);if(!source||source.status!=='planned')return ['Only planned sessions can be moved.'];if(sessions.some(s=>s.id!==id&&s.date===date&&s.status==='planned'))return ['Another session is already scheduled for that day.'];if(source.kind==='strength'&&sessions.some(s=>s.id!==id&&s.kind==='strength'&&s.status!=='skipped'&&Math.abs(difference(s.date,date))<2))return ['Leave a recovery day between full body strength sessions.'];if(source.kind==='run'&&source.goal==='running'&&sessions.some(s=>s.id!==id&&s.kind==='run'&&s.status!=='skipped'&&Math.abs(difference(s.date,date))<2))return ['Leave a recovery day between foundation runs.'];return [];}
export function substitutions(item,p,location){const e=exerciseById(item.exerciseId);return EXERCISES.filter(x=>x.pattern===e.pattern&&x.id!==e.id&&eligible(x,p,location));}
export function progressionFor(exerciseId,history,applied={}){const latest=history.filter(h=>h.sets?.some(s=>s.exerciseId===exerciseId)).slice(-2);if(latest.length<2||applied?.[exerciseId]&&applied[exerciseId]===latest.at(-1)?.id)return {ready:false,reason:'Record this movement in two sessions at its current target before considering an increase.'};const first=latest[0].sets.filter(s=>s.exerciseId===exerciseId),second=latest[1].sets.filter(s=>s.exerciseId===exerciseId);const sameTarget=first.length===second.length&&first.every((s,i)=>s.targetMax===second[i].targetMax&&s.kg===second[i].kg&&s.band===second[i].band);const ok=sameTarget&&latest.every(h=>!h.discomfort&&!h.tooHard&&h.status==='completed'&&h.sets.filter(s=>s.exerciseId===exerciseId).every(s=>s.reps>=s.targetMax&&s.effort==='more'&&!s.discomfort)&&h.prescription?.find(i=>i.exerciseId===exerciseId)?.sets===h.sets.filter(s=>s.exerciseId===exerciseId).length);return {ready:ok,reason:ok?'You reached the top of the range with controlled effort in two sessions. Consider one small increase.':'Repeat this movement. Completion and effort do not yet support an increase.'};}
export function calendarICS(sessions,p){const esc=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Home training//Workout calendar//EN','CALSCALE:GREGORIAN'];for(const s of sessions.filter(s=>s.status==='planned')){const [h,m]=p.time.split(':').map(Number);let t=Date.parse(s.date+'T00:00:00Z')+(h*60+m)*60000;const parts=new Intl.DateTimeFormat('en-GB',{timeZone:p.timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(t));const localH=+parts.find(x=>x.type==='hour').value,localM=+parts.find(x=>x.type==='minute').value;let off=(localH*60+localM)-(h*60+m);if(off>720)off-=1440;if(off<-720)off+=1440;t-=off*60000;const stamp=x=>new Date(x).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');lines.push('BEGIN:VEVENT',`UID:${s.id}@home-training`,`DTSTAMP:${stamp(Date.now())}`,`DTSTART:${stamp(t)}`,`DTEND:${stamp(t+(s.kind==='run'?s.runMinutes*60:estimateSession(s))*1000)}`,`SUMMARY:${esc(s.title)}`,`DESCRIPTION:${esc('Home training. '+(s.note||''))}`,'BEGIN:VALARM','TRIGGER:-PT15M','ACTION:DISPLAY','DESCRIPTION:Workout in 15 minutes','END:VALARM','END:VEVENT');}lines.push('END:VCALENDAR');const encoder=new TextEncoder();return lines.map(line=>{const folded=[];let current='',bytes=0;for(const char of line){const size=encoder.encode(char).length;if(bytes+size>73){folded.push(current);current=' '+char;bytes=1+size;}else{current+=char;bytes+=size;}}folded.push(current);return folded.join('\r\n');}).join('\r\n')+'\r\n';}
